1	interface Item {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	}
6	
7	interface QuoteStep {
8	  op: "quote";
9	  items: Item[];
10	}
11	
12	interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	interface ClaimStep {
18	  op: "claim";
19	  policy: number;
20	  incident: { cause: string; damages: Damage[] };
21	}
22	
23	type Step = QuoteStep | ClaimStep;
24	
25	interface Scenario {
26	  customer: { yearsWithMHPCO: number };
27	  steps: Step[];
28	}
29	
30	interface QuoteResult {
31	  premium: number;
32	}
33	
34	interface ClaimResult {
35	  payout: number;
36	  remainingCap: number;
37	}
38	
39	type StepResult = QuoteResult | ClaimResult;
40	
41	const BASE_PREMIUM: Record<string, number> = {
42	  sword: 100,
43	  amulet: 60,
44	  staff: 80,
45	  potion: 40,
46	  rune: 25,
47	};
48	
49	// The item types the office insures, mapped to their insured value. Doubles as
50	// the registry of "known" types for quote validation (isKnownType) and as the
51	// basis for a policy's cap (insuranceSum).
52	const INSURANCE_VALUE: Record<string, number> = {
53	  sword: 1000,
54	  amulet: 600,
55	  staff: 800,
56	  potion: 400,
57	  rune: 250,
58	  moonstone: 250,
59	};
60	
61	const PROCESSING_FEE = 5;
62	const FIRST_INSURANCE_SURCHARGE = 0.1;
63	
64	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
65	const COMPONENT_UNIT_PREMIUM = 25;
66	const COMPONENT_BLOCK_SIZE = 3;
67	const COMPONENT_BLOCK_PREMIUM = 60;
68	
69	// Tally how many times each value appears, keyed by the value.
70	const countByType = (types: string[]): Map<string, number> => {
71	  const counts = new Map<string, number>();
72	  for (const type of types) {
73	    counts.set(type, (counts.get(type) ?? 0) + 1);
74	  }
75	  return counts;
76	};
77	
78	const componentGroupBase = (count: number): number =>
79	  count === COMPONENT_BLOCK_SIZE
80	    ? COMPONENT_BLOCK_PREMIUM
81	    : count * COMPONENT_UNIT_PREMIUM;
82	
83	const componentsBase = (components: Item[]): number => {
84	  const countsByType = countByType(components.map((component) => component.type));
85	  return [...countsByType.values()].reduce(
86	    (total, count) => total + componentGroupBase(count),
87	    0,
88	  );
89	};
90	
91	const isComponent = (item: Item): boolean =>
92	  COMPONENT_TYPES.has(item.type);
93	
94	const itemsBase = (items: Item[]): number => {
95	  const mainBase = items
96	    .filter((item) => !isComponent(item))
97	    .reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
98	  return mainBase + componentsBase(items.filter(isComponent));
99	};
100	
101	const CURSE_SURCHARGE = 0.5;
102	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
103	const HIGH_ENCHANTMENT_THRESHOLD = 5;
104	
105	// Sum `rate * base premium` for every item matching `applies`. The additive
106	// per-item form keeps each surcharge a flat term so quotePremium stays additive
107	// (see the float-drift note there).
108	const itemSurcharge = (
109	  items: Item[],
110	  applies: (item: Item) => boolean,
111	  rate: number,
112	): number =>
113	  items.reduce(
114	    (sum, item) => sum + (applies(item) ? BASE_PREMIUM[item.type] * rate : 0),
115	    0,
116	  );
117	
118	const curseSurcharge = (items: Item[]): number =>
119	  itemSurcharge(items, (item) => item.cursed === true, CURSE_SURCHARGE);
120	
121	const highEnchantmentSurcharge = (items: Item[]): number =>
122	  itemSurcharge(
123	    items,
124	    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
125	    HIGH_ENCHANTMENT_SURCHARGE,
126	  );
127	
128	const LOYALTY_DISCOUNT = 0.2;
129	const LOYALTY_THRESHOLD_YEARS = 2;
130	const FOLLOWUP_DISCOUNT = 0.15;
131	
132	const loyaltyDiscount = (base: number, yearsWithMHPCO: number): number =>
133	  yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? base * LOYALTY_DISCOUNT : 0;
134	
135	const followupDiscount = (base: number, isFollowup: boolean): number =>
136	  isFollowup ? base * FOLLOWUP_DISCOUNT : 0;
137	
138	// Always-on surcharge charged on every policy, expressed as a flat term so
139	// quotePremium stays additive (see the float-drift note there).
140	const firstInsuranceSurcharge = (base: number): number =>
141	  base * FIRST_INSURANCE_SURCHARGE;
142	
143	const isKnownType = (type: string): boolean => type in INSURANCE_VALUE;
144	
145	const assertKnownItems = (items: Item[]): void => {
146	  const unknown = items.find((item) => !isKnownType(item.type));
147	  if (unknown !== undefined) {
148	    throw new Error(`Unknown item type: ${unknown.type}`);
149	  }
150	};
151	
152	const quotePremium = (
153	  items: Item[],
154	  yearsWithMHPCO: number,
155	  isFollowup: boolean,
156	): number => {
157	  assertKnownItems(items);
158	  const base = itemsBase(items);
159	  const surcharges =
160	    firstInsuranceSurcharge(base) +
161	    curseSurcharge(items) +
162	    highEnchantmentSurcharge(items);
163	  const discounts =
164	    loyaltyDiscount(base, yearsWithMHPCO) + followupDiscount(base, isFollowup);
165	  // Sum flat terms rather than scaling `base * (1 + rate)`: the additive form
166	  // avoids IEEE-754 drift that would otherwise round wrong under Math.ceil.
167	  return Math.ceil(base + surcharges - discounts + PROCESSING_FEE);
168	};
169	
170	const DEDUCTIBLE = 100;
171	const CAP_MULTIPLIER = 2;
172	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
173	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
174	
175	const insuranceSum = (items: Item[]): number =>
176	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
177	
178	// Reimbursement for a single damage before the deductible. Items enchanted to
179	// level 8+ are reimbursed at only 50% of the damage amount.
180	const reimbursement = (item: Item, amount: number): number =>
181	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
182	    ? amount * HIGH_ENCHANTMENT_REIMBURSEMENT
183	    : amount;
184	
185	// The policy item a damage refers to, matched by type. Throws if the damage
186	// references an item the policy does not cover.
187	const policyItemFor = (damage: Damage, policyItems: Item[]): Item => {
188	  const item = policyItems.find((i) => i.type === damage.itemType);
189	  if (item === undefined) {
190	    throw new Error(`Item not in policy: ${damage.itemType}`);
191	  }
192	  return item;
193	};
194	
195	// Each damaged item is reimbursed (subject to clauses) less one deductible,
196	// floored in MHPCO's favor.
197	const damagesPayout = (damages: Damage[], policyItems: Item[]): number =>
198	  Math.floor(
199	    damages.reduce((sum, damage) => {
200	      const item = policyItemFor(damage, policyItems);
201	      return sum + (reimbursement(item, damage.amount) - DEDUCTIBLE);
202	    }, 0),
203	  );
204	
205	const claimResult = (
206	  claim: ClaimStep,
207	  policyItems: Item[],
208	  remainingCap: number,
209	): ClaimResult => {
210	  const desired = damagesPayout(claim.incident.damages, policyItems);
211	  const payout = Math.min(desired, remainingCap);
212	  return { payout, remainingCap: remainingCap - payout };
213	};
214	
215	// A damage amount must be a real loss, so a negative amount is rejected outright.
216	const assertNonNegativeDamages = (claim: ClaimStep): void => {
217	  const negative = claim.incident.damages.find((damage) => damage.amount < 0);
218	  if (negative !== undefined) {
219	    throw new Error(`Negative damage amount: ${negative.amount}`);
220	  }
221	};
222	
223	// A claim may not report more damages of a type than the policy insures — you
224	// can't lose three swords under a policy that covers two.
225	const assertDamageCountWithinPolicy = (claim: ClaimStep, policyItems: Item[]): void => {
226	  const insured = countByType(policyItems.map((item) => item.type));
227	  const damaged = countByType(claim.incident.damages.map((damage) => damage.itemType));
228	  for (const [type, count] of damaged) {
229	    if (count > (insured.get(type) ?? 0)) {
230	      throw new Error(`Too many damages for item type: ${type}`);
231	    }
232	  }
233	};
234	
235	const settleClaim = (
236	  claim: ClaimStep,
237	  steps: Step[],
238	  remainingCapByPolicy: Map<number, number>,
239	): ClaimResult => {
240	  const policyItems = (steps[claim.policy] as QuoteStep).items;
241	  assertNonNegativeDamages(claim);
242	  assertDamageCountWithinPolicy(claim, policyItems);
243	  // A policy's cap starts at twice its insurance sum and is drawn down by each
244	  // claim. remainingCapByPolicy tracks the running balance keyed by policy step
245	  // index, seeding the initial cap the first time a policy is claimed against.
246	  const remainingCap =
247	    remainingCapByPolicy.get(claim.policy) ??
248	    CAP_MULTIPLIER * insuranceSum(policyItems);
249	  const result = claimResult(claim, policyItems, remainingCap);
250	  remainingCapByPolicy.set(claim.policy, result.remainingCap);
251	  return result;
252	};
253	
254	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
255	  const remainingCapByPolicy = new Map<number, number>();
256	  const results = scenario.steps.map((step, index): StepResult => {
257	    if (step.op === "claim") {
258	      return settleClaim(step, scenario.steps, remainingCapByPolicy);
259	    }
260	    // Every quote after the first is a follow-up contract; the map index is
261	    // already the count of quotes seen so far, so no separate counter is needed.
262	    const isFollowup = index > 0;
263	    return {
264	      premium: quotePremium(step.items, scenario.customer.yearsWithMHPCO, isFollowup),
265	    };
266	  });
267	  return { results };
268	};
